export function calculateJitteredTtl(
  baseTtlSeconds: number,
  maxJitterSeconds = 300
): number {
  // Add a uniform random offset (e.g., 3600s + 0..300s)
  const jitter = Math.floor(Math.random() * maxJitterSeconds);
  return baseTtlSeconds + jitter;
}

// Usage in cache write:
await redis.set(
  `catalog:product:${productId}`,
  JSON.stringify(productData),
  'EX',
  calculateJitteredTtl(3600, 300)
);
